enum PaymentMethod {
    case cash
    case card(lastFour: String)
}

func label(for method: PaymentMethod) -> String {
    switch method {
    case .cash:
        return "Cash"
    case .card({{2}} lastFour):
        return "Card ending \(lastFour)"
    }
}
